command:
$ErrorActionPreference="Stop"
$repo="C:\dev\flyExplorer"
$branch="work/current-release-packaging-final-20261005"
$candidate="067122c8e9b45d56c4fa8dde75fef9c2ef86f44f"
$main="0ba7feb43a8a18562c78396abaa2a436455806b4"
Set-Location -LiteralPath $repo
& git fetch origin $branch main --no-tags --prune
if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
$temp=Join-Path $env:RUNNER_TEMP ("packaging-final-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & python -X utf8 tools\winui\check_python_static.py packaging\package.py packaging\provenance.py tools\winui\diagnose_installed_shutdown.py tests\winui\test_installed_lifecycle.py tests\winui\test_installer_contract.py tests\winui\test_release_payload_contract.py
  if($LASTEXITCODE -ne 0){throw "packaging Python static check failed"}
  & python -X utf8 -m unittest tests.winui.test_installer_contract tests.winui.test_release_payload_contract
  if($LASTEXITCODE -ne 0){throw "packaging contracts failed"}
  & git diff --check "$main..$candidate"
  if($LASTEXITCODE -ne 0){throw "candidate diff check failed"}

  & .\clean.bat build
  if($LASTEXITCODE -ne 0){throw "clean build output failed"}
  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "canonical Release build failed"}

  & python -X utf8 packaging\provenance.py --write
  if($LASTEXITCODE -ne 0){throw "payload provenance generation failed"}
  & python -X utf8 packaging\provenance.py --check
  if($LASTEXITCODE -ne 0){throw "payload provenance verification failed"}

  & .\package.bat Release
  if($LASTEXITCODE -ne 0){throw "current Release package build failed"}

  $evidence=$env:FLYEXPLORER_REMOTE_EVIDENCE_DIR
  New-Item -ItemType Directory -Force -Path $evidence | Out-Null
  Copy-Item -LiteralPath "packaging\licenses\PAYLOAD_PROVENANCE.json" -Destination (Join-Path $evidence "PAYLOAD_PROVENANCE.json") -Force
  Copy-Item -LiteralPath "packaging\licenses\PAYLOAD_PROVENANCE.md" -Destination (Join-Path $evidence "PAYLOAD_PROVENANCE.md") -Force

  & python -X utf8 tests\winui\test_installed_lifecycle.py
  if($LASTEXITCODE -ne 0){throw "bounded installed lifecycle failed"}

  Write-Host "CURRENT_RELEASE_PACKAGING_FINAL_PASS"
}finally{
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
